const https = require('https');
const req = https.request({ hostname: 'api.ivxholding.com', path: '/health', method: 'GET', headers: { 'Accept': 'application/json' }, timeout: 15000 }, res => {
  let data = '';
  res.on('data', chunk => data += chunk);
  res.on('end', () => {
    try {
      const j = JSON.parse(data);
      console.log('Status:', res.statusCode);
      console.log('commitSha:', j.commitSha);
      console.log('bootTime:', j.bootTime);
      console.log('status:', j.status);
    } catch(e) { console.log('raw:', data.slice(0,2000)); }
  });
});
req.on('error', err => console.log('ERROR:', err.message));
req.end();
" 2>&1

